/* =====================================================================
   engine.schema.js  —  Engine.Schema   (blueprint §15)

   Turns an entity model into:
     - real SQL migrations (CREATE TABLE / FK / INDEX / UNIQUE INDEX, up+down)
     - a machine schema (src/schema.js) the data layer validates against
     - a dependency-free data layer (src/db.js) that ENFORCES the schema:
       types, required, max length, defaults, auto-increment ids, timestamps,
       foreign-key existence, unique indexes, and cascade-on-delete.
     - a relation / query analysis (N+1 hints, missing FK indexes).

   Portable by design: the data layer is a JSON-file store, so `npm test`
   really runs and the runtime observer can really drive the app. The SQL
   migrations are the real artefact for moving to Postgres later.

   window.Engine.Schema
     TYPES
     normalizeSpec(spec)          -> canonical { name, entities:[...] }
     migrationsSQL(spec)          -> { 'db/migrations/001_init.sql': '...' , down }
     schemaModule(spec)           -> src/schema.js source
     dbModule(spec)               -> src/db.js source
     analyze(spec)                -> { hints:[...], indexesSuggested:[...] }
   ===================================================================== */
(function () {
  'use strict';
  var Engine = window.Engine || (window.Engine = {});

  // field type -> { sql, js default check }
  var TYPES = {
    id:        { sql: 'INTEGER PRIMARY KEY AUTOINCREMENT', js: 'number', auto: true },
    text:      { sql: 'TEXT', js: 'string' },
    longtext:  { sql: 'TEXT', js: 'string' },
    int:       { sql: 'INTEGER', js: 'number' },
    float:     { sql: 'REAL', js: 'number' },
    bool:      { sql: 'INTEGER', js: 'boolean' },
    json:      { sql: 'TEXT', js: 'object' },
    timestamp: { sql: 'TEXT', js: 'string' },
    ref:       { sql: 'INTEGER', js: 'number', fk: true }
  };

  function ident(s) { return String(s || '').replace(/[^a-zA-Z0-9_]/g, '').replace(/^(\d)/, '_$1') || 'x'; }
  function tableOf(name) { return ident(name).toLowerCase() + (/s$/.test(name) ? '' : 's'); }
  function singular(name) { return ident(name).toLowerCase().replace(/s$/, ''); }

  function normalizeSpec(spec) {
    spec = spec || {};
    var name = ident(spec.name || 'app') || 'app';
    var entities = (spec.entities || []).map(function (e) {
      var en = singular(e.name || 'item');
      var fields = (e.fields || []).slice();
      if (!fields.some(function (f) { return f.type === 'id' || f.name === 'id'; })) fields.unshift({ name: 'id', type: 'id' });
      if (!fields.some(function (f) { return f.name === 'createdAt'; })) fields.push({ name: 'createdAt', type: 'timestamp', default: 'now' });
      fields = fields.map(function (f) {
        var t = TYPES[f.type] ? f.type : (f.ref ? 'ref' : 'text');
        // idempotent: accept both raw ({default}) and already-normalized ({def})
        var d = f.default !== undefined ? f.default : (f.def !== undefined ? f.def : null);
        return {
          name: ident(f.name), type: t,
          required: !!f.required && t !== 'id',
          max: f.max || (t === 'text' ? 500 : null),
          def: d,
          ref: t === 'ref' ? singular(f.ref || (f.name.replace(/Id$/, '') || 'user')) : null,
          onDelete: f.onDelete || (t === 'ref' ? 'cascade' : null)
        };
      });
      var indexes = (e.indexes || []).map(function (ix) {
        return Array.isArray(ix) ? { fields: ix.map(ident), unique: false } : { fields: (ix.fields || []).map(ident), unique: !!ix.unique };
      });
      // auto-index every FK
      fields.filter(function (f) { return f.type === 'ref'; }).forEach(function (f) {
        if (!indexes.some(function (ix) { return ix.fields.length === 1 && ix.fields[0] === f.name; })) indexes.push({ fields: [f.name], unique: false });
      });
      return { name: en, table: tableOf(e.name || en), fields: fields, indexes: indexes, ownable: e.ownable !== false && fields.some(function (f) { return f.type === 'ref' && f.ref === 'user'; }) };
    });
    return { name: name, entities: entities, auth: !!spec.auth };
  }

  function colSQL(f) {
    var parts = ['  ' + f.name + ' ' + TYPES[f.type].sql];
    if (f.type !== 'id') {
      if (f.required) parts.push('NOT NULL');
      if (f.def !== null && f.def !== 'now') parts.push('DEFAULT ' + (typeof f.def === 'string' ? "'" + f.def.replace(/'/g, "''") + "'" : (f.def === true ? 1 : f.def === false ? 0 : f.def)));
    }
    return parts.join(' ');
  }

  function migrationsSQL(spec) {
    var s = normalizeSpec(spec);
    var up = ['-- ' + s.name + ' — initial schema', '-- generated by CodeSovereign Engine.Schema', ''];
    var down = ['-- rollback 001_init', ''];
    s.entities.forEach(function (e) {
      var lines = ['CREATE TABLE IF NOT EXISTS ' + e.table + ' ('];
      var body = e.fields.map(colSQL);
      e.fields.filter(function (f) { return f.type === 'ref'; }).forEach(function (f) {
        body.push('  FOREIGN KEY (' + f.name + ') REFERENCES ' + tableOf(f.ref) + '(id) ON DELETE ' + (f.onDelete === 'cascade' ? 'CASCADE' : 'SET NULL'));
      });
      lines.push(body.join(',\n'));
      lines.push(');');
      up.push(lines.join('\n'));
      e.indexes.forEach(function (ix) {
        var nm = 'idx_' + e.table + '_' + ix.fields.join('_');
        up.push('CREATE ' + (ix.unique ? 'UNIQUE ' : '') + 'INDEX IF NOT EXISTS ' + nm + ' ON ' + e.table + ' (' + ix.fields.join(', ') + ');');
        down.push('DROP INDEX IF EXISTS ' + nm + ';');
      });
      up.push('');
      down.push('DROP TABLE IF EXISTS ' + e.table + ';');
    });
    return { 'db/migrations/001_init.sql': up.join('\n') + '\n', 'db/migrations/001_init.down.sql': down.join('\n') + '\n' };
  }

  function schemaModule(spec) {
    var s = normalizeSpec(spec);
    return "'use strict';\n" +
      "// Machine schema — the data layer validates every write against this.\n" +
      "module.exports = " + JSON.stringify({
        name: s.name,
        entities: s.entities.map(function (e) {
          return { name: e.name, table: e.table, ownable: e.ownable,
            fields: e.fields.map(function (f) { return { name: f.name, type: f.type, required: f.required, max: f.max, def: f.def, ref: f.ref, onDelete: f.onDelete }; }),
            indexes: e.indexes };
        })
      }, null, 2) + ";\n";
  }

  function dbModule() {
    // one generic, schema-driven JSON store (identical for every generated app)
    return [
      "'use strict';",
      "// Dependency-free data layer. Honours db/migrations via src/schema.js:",
      "// types, required, max, defaults, auto-inc ids, timestamps, FK existence,",
      "// unique indexes, ON DELETE CASCADE. Swap for `pg` when you deploy.",
      "const fs = require('fs');",
      "const path = require('path');",
      "const schema = require('./schema');",
      "",
      "const DIR = process.env.DATA_DIR ? path.resolve(process.env.DATA_DIR) : path.join(__dirname, '..', '.data');",
      "const file = (t) => path.join(DIR, t + '.json');",
      "function safeWrite(p, s) { try { fs.mkdirSync(DIR, { recursive: true }); fs.writeFileSync(p, s); } catch (e) { if (e.code !== 'ENOENT') throw e; fs.mkdirSync(DIR, { recursive: true }); fs.writeFileSync(p, s); } }",
      "function ent(name) { const e = schema.entities.find((x) => x.name === name || x.table === name); if (!e) throw new Error('unknown entity ' + name); return e; }",
      "function load(e) { try { return JSON.parse(fs.readFileSync(file(e.table), 'utf8')); } catch (_) { return { rows: [], seq: 0 }; } }",
      "function save(e, d) { safeWrite(file(e.table), JSON.stringify(d, null, 2)); }",
      "",
      "function coerce(f, v) {",
      "  if (v == null) return v;",
      "  if (f.type === 'bool') return !!v;",
      "  if (f.type === 'int' || f.type === 'float' || f.type === 'ref') return Number(v);",
      "  if (f.type === 'json') return typeof v === 'string' ? v : JSON.stringify(v);",
      "  return String(v);",
      "}",
      "function validate(e, obj, partial) {",
      "  const out = {};",
      "  for (const f of e.fields) {",
      "    if (f.type === 'id') continue;",
      "    let v = obj[f.name];",
      "    if (v === undefined) { if (partial) continue; if (f.def === 'now') v = new Date().toISOString(); else if (f.def != null) v = f.def; }",
      "    if ((v == null || v === '') && f.required) throw Object.assign(new Error(f.name + ' is required'), { status: 400 });",
      "    if (v != null) { v = coerce(f, v); if (f.max && typeof v === 'string' && v.length > f.max) v = v.slice(0, f.max); }",
      "    if (v !== undefined) out[f.name] = v;",
      "  }",
      "  return out;",
      "}",
      "async function checkFKs(e, obj) {",
      "  for (const f of e.fields) {",
      "    if (f.type !== 'ref' || obj[f.name] == null) continue;",
      "    const ref = ent(f.ref);",
      "    const d = load(ref);",
      "    if (!d.rows.some((r) => r.id === Number(obj[f.name]))) throw Object.assign(new Error(f.name + ' -> ' + ref.table + ' not found'), { status: 400 });",
      "  }",
      "}",
      "function checkUnique(e, d, obj, ignoreId) {",
      "  for (const ix of (e.indexes || [])) {",
      "    if (!ix.unique) continue;",
      "    const clash = d.rows.some((r) => r.id !== ignoreId && ix.fields.every((k) => obj[k] !== undefined ? r[k] === obj[k] : true));",
      "    if (clash) throw Object.assign(new Error('duplicate for unique index (' + ix.fields.join(',') + ')'), { status: 409 });",
      "  }",
      "}",
      "",
      "async function create(name, input) {",
      "  const e = ent(name); const d = load(e);",
      "  const obj = validate(e, input, false);",
      "  await checkFKs(e, obj); checkUnique(e, d, obj, -1);",
      "  const row = Object.assign({ id: ++d.seq }, obj);",
      "  d.rows.push(row); save(e, d); return row;",
      "}",
      "async function list(name, opts) {",
      "  const e = ent(name); const d = load(e); opts = opts || {};",
      "  let rows = d.rows.slice();",
      "  for (const k of Object.keys(opts.where || {})) rows = rows.filter((r) => String(r[k]) === String(opts.where[k]));",
      "  rows.sort((a, b) => (b.id - a.id));",
      "  const offset = Number(opts.offset || 0), limit = Math.min(Number(opts.limit || 100), 500);",
      "  return { total: rows.length, rows: rows.slice(offset, offset + limit) };",
      "}",
      "async function get(name, id) { const e = ent(name); return load(e).rows.find((r) => r.id === Number(id)) || null; }",
      "async function update(name, id, input) {",
      "  const e = ent(name); const d = load(e); const i = d.rows.findIndex((r) => r.id === Number(id));",
      "  if (i < 0) return null;",
      "  const patch = validate(e, input, true);",
      "  await checkFKs(e, patch); checkUnique(e, d, Object.assign({}, d.rows[i], patch), Number(id));",
      "  d.rows[i] = Object.assign({}, d.rows[i], patch); save(e, d); return d.rows[i];",
      "}",
      "async function remove(name, id) {",
      "  const e = ent(name); const d = load(e); const before = d.rows.length;",
      "  d.rows = d.rows.filter((r) => r.id !== Number(id)); save(e, d);",
      "  // ON DELETE CASCADE",
      "  for (const child of schema.entities) for (const f of child.fields)",
      "    if (f.type === 'ref' && f.ref === e.name && (f.onDelete === 'cascade')) {",
      "      const cd = load(child); cd.rows = cd.rows.filter((r) => r[f.name] !== Number(id)); save(child, cd);",
      "    }",
      "  return before !== d.rows.length;",
      "}",
      "async function reset() { try { fs.rmSync(DIR, { recursive: true, force: true }); } catch (_) {} fs.mkdirSync(DIR, { recursive: true }); }",
      "async function migrate() { fs.mkdirSync(DIR, { recursive: true }); for (const e of schema.entities) if (!fs.existsSync(file(e.table))) save(e, { rows: [], seq: 0 }); return schema.entities.map((e) => e.table); }",
      "",
      "module.exports = { create, list, get, update, remove, reset, migrate, schema };",
      ""
    ].join('\n');
  }

  // node-pg stack: src/db.js becomes a shim that picks pg (DATABASE_URL set) or
  // the JSON store. Migrations are already real SQL — `npm run migrate` runs
  // them against Postgres.
  function dbShim() {
    return "'use strict';\n" +
      "// Picks the real Postgres adapter when DATABASE_URL is set, else the\n" +
      "// dependency-free JSON store (used by the tests and for local dev).\n" +
      "module.exports = process.env.DATABASE_URL ? require('./db.pg') : require('./db.json');\n";
  }
  function pgModule(spec) {
    var s = normalizeSpec(spec);
    return [
      "'use strict';",
      "// Real Postgres data layer — same interface as db.json. Needs `pg`",
      "// (optionalDependency) and DATABASE_URL. Run migrations with npm run migrate.",
      "const schema = require('./schema');",
      "// pg is an optionalDependency — loaded lazily so the app still starts (on the",
      "// JSON store, via db.js) when it isn't installed.",
      "let _pool;",
      "function pool() {",
      "  if (!_pool) { const { Pool } = require('pg'); _pool = new Pool({ connectionString: process.env.DATABASE_URL, max: 10 }); }",
      "  return _pool;",
      "}",
      "function ent(name) { const e = schema.entities.find((x) => x.name === name || x.table === name); if (!e) throw new Error('unknown entity ' + name); return e; }",
      "const q = (text, params) => pool().query(text, params);",
      "",
      "async function migrate() {",
      "  const fs = require('fs'); const path = require('path');",
      "  const dir = path.join(__dirname, '..', 'db', 'migrations');",
      "  for (const f of fs.readdirSync(dir).filter((x) => /^\\d+_.*\\.sql$/.test(x) && !/\\.down\\./.test(x)).sort())",
      "    await q(fs.readFileSync(path.join(dir, f), 'utf8'));",
      "  return schema.entities.map((e) => e.table);",
      "}",
      "async function create(name, input) {",
      "  const e = ent(name); const cols = e.fields.filter((f) => f.type !== 'id' && input[f.name] !== undefined);",
      "  const now = e.fields.find((f) => f.name === 'createdAt'); if (now && input.createdAt === undefined) { cols.push(now); input.createdAt = new Date().toISOString(); }",
      "  const names = cols.map((f) => f.name); const vals = names.map((n) => input[n]);",
      "  const ph = names.map((_, i) => '$' + (i + 1)).join(', ');",
      "  const { rows } = await q('INSERT INTO ' + e.table + ' (' + names.join(', ') + ') VALUES (' + ph + ') RETURNING *', vals);",
      "  return rows[0];",
      "}",
      "async function list(name, opts) {",
      "  const e = ent(name); opts = opts || {}; const where = opts.where || {};",
      "  const keys = Object.keys(where); const cond = keys.map((k, i) => k + ' = $' + (i + 1));",
      "  const base = 'FROM ' + e.table + (cond.length ? ' WHERE ' + cond.join(' AND ') : '');",
      "  const total = Number((await q('SELECT count(*) ' + base, keys.map((k) => where[k]))).rows[0].count);",
      "  const { rows } = await q('SELECT * ' + base + ' ORDER BY id DESC LIMIT ' + Math.min(Number(opts.limit || 100), 500) + ' OFFSET ' + Number(opts.offset || 0), keys.map((k) => where[k]));",
      "  return { total, rows };",
      "}",
      "async function get(name, id) { const e = ent(name); return (await q('SELECT * FROM ' + e.table + ' WHERE id = $1', [id])).rows[0] || null; }",
      "async function update(name, id, input) {",
      "  const e = ent(name); const cols = e.fields.filter((f) => f.type !== 'id' && input[f.name] !== undefined).map((f) => f.name);",
      "  if (!cols.length) return get(name, id);",
      "  const set = cols.map((c, i) => c + ' = $' + (i + 2)).join(', ');",
      "  const { rows } = await q('UPDATE ' + e.table + ' SET ' + set + ' WHERE id = $1 RETURNING *', [id].concat(cols.map((c) => input[c])));",
      "  return rows[0] || null;",
      "}",
      "async function remove(name, id) { const e = ent(name); const r = await q('DELETE FROM ' + e.table + ' WHERE id = $1', [id]); return r.rowCount > 0; }",
      "async function reset() { for (const e of schema.entities.slice().reverse()) await q('TRUNCATE ' + e.table + ' RESTART IDENTITY CASCADE').catch(() => {}); }",
      "module.exports = { create, list, get, update, remove, reset, migrate, schema };",
      ""
    ].join('\n');
  }

  function analyze(spec) {
    var s = normalizeSpec(spec);
    var hints = [];
    s.entities.forEach(function (e) {
      e.fields.filter(function (f) { return f.type === 'ref'; }).forEach(function (f) {
        var hasIx = e.indexes.some(function (ix) { return ix.fields.indexOf(f.name) >= 0; });
        if (!hasIx) hints.push({ kind: 'missing-fk-index', entity: e.name, field: f.name });
        hints.push({ kind: 'n+1-risk', entity: e.name, field: f.name,
          note: 'listing ' + e.table + ' then loading each ' + f.ref + ' one-by-one is N+1 — batch the ' + f.ref + ' lookup' });
      });
    });
    return { entities: s.entities.length, hints: hints };
  }

  Engine.Schema = { TYPES: TYPES, normalizeSpec: normalizeSpec, migrationsSQL: migrationsSQL, schemaModule: schemaModule, dbModule: dbModule, dbShim: dbShim, pgModule: pgModule, analyze: analyze, tableOf: tableOf, singular: singular };
  console.info('[Schema] schema + migration + data-layer engine ready — Engine.Schema');
})();
